<?php
if($page==='documents'){
    heading('DOCUMENTS COMMERCIAUX','Devis, factures & avoirs.','Préparez vos devis commerciaux avant la commande ; émettez les factures depuis la commande.');
    $kind=in_array($_GET['kind']??'',['quote','invoice','credit'],true)?$_GET['kind']:'';$args=[];$where='1=1';if($kind!==''){$where.=' AND d.kind=?';$args[]=$kind;}
    $count=(int)scalar('SELECT COUNT(*) FROM documents d WHERE '.$where,$args);$current=max(1,min(max(1,(int)ceil($count/20)),(int)($_GET['p']??1)));$offset=($current-1)*20;
    $docs=all('SELECT d.* FROM documents d WHERE '.$where.' ORDER BY d.id DESC LIMIT 20 OFFSET '.$offset,$args);
    ?><section class="panel"><form method="get" class="filter-bar"><input type="hidden" name="page" value="documents"><select name="kind" aria-label="Type de document"><option value="">Tous les documents</option><option value="quote" <?=$kind==='quote'?'selected':''?>>Devis</option><option value="invoice" <?=$kind==='invoice'?'selected':''?>>Factures</option><option value="credit" <?= $kind==='credit'?'selected':'' ?>>Avoirs</option></select><button class="btn secondary">Filtrer</button><a class="btn primary" href="<?=e(url('quotes'))?>">Devis commerciaux</a><a class="btn secondary" href="<?=e(url('orders'))?>">Commandes</a></form><?php if(!$docs):emptyState('Aucun document.','Ouvrez une commande pour créer son devis ou sa facture.');else:?><div class="table-scroll"><table><thead><tr><th>DOCUMENT</th><th>CLIENT À L’ÉMISSION</th><th>ÉMIS LE</th><th class="numeric">TOTAL TTC</th><th>PDF</th></tr></thead><tbody><?php foreach($docs as $d):$snap=json_decode($d['snapshot'],true);?><tr><td><a class="record-title" href="<?=e(url('document',['id'=>$d['id']]))?>"><?=e($d['number'])?></a><small class="subline"><?=$d['order_id']?e(ref((int)$d['order_id'])):'Sans commande'?><?=$d['kind']==='quote'?' · '.e(quoteLabel($d)):''?></small></td><td><?=e($snap['client']['company'])?></td><td><?=e(localDate($d['created_at']))?></td><td class="numeric"><?=e(money($d['total']))?></td><td><a class="btn secondary" href="<?=e(url('document',['id'=>$d['id'],'download'=>'pdf']))?>">↓ PDF</a></td></tr><?php endforeach?></tbody></table></div><?php pagination($count,$current,'documents',['kind'=>$kind]);endif?></section><?php return;
}
$id=max(0,(int)($_GET['id']??0));$doc=row('SELECT * FROM documents WHERE id=?',[$id]);if(!$doc){emptyState('Document introuvable.','Revenez aux documents.','Documents',url('documents'));return;}
$s=json_decode($doc['snapshot'],true,512,JSON_THROW_ON_ERROR);$i=$s['issuer'];$c=$s['client'];$o=$s['order'];$summary=$doc['order_id']?paymentSummary((int)$doc['order_id']):emptyPaymentSummary();
heading('DOCUMENT COMMERCIAL',$doc['number'],documentType($doc).' · coordonnées et montants conservés');
?><div class="document-actions"><a class="btn secondary" href="<?=e($doc['order_id']?url('order_form',['id'=>$doc['order_id']]):url('quotes'))?>"><?=$doc['order_id']?'← Commande':'← Devis'?></a><a class="btn primary" href="<?=e(url('document',['id'=>$id,'download'=>'pdf']))?>">↓ Télécharger le PDF</a></div><?php require __DIR__.'/quote_workflow_view.php';require __DIR__.'/credit_workflow_view.php';?><article class="document-sheet"><header><div><h1><?=e($i['company_name'])?></h1><p>Impression & services publicitaires</p></div><div><h2><?=e(mb_strtoupper(documentType($doc)))?></h2><strong><?=e($doc['number'])?></strong><p><?=e(localDate($doc['created_at']))?></p></div></header><div class="document-parties"><section><h3>Émetteur</h3><p><?=nl2br(e($i['company_address']))?></p><p><?=e($i['company_phone'])?> · <?=e($i['company_email'])?></p><p>ICE : <?=e($i['company_ice'])?:'—'?> · IF : <?=e($i['company_if'])?:'—'?></p><p>RC : <?=e($i['company_rc'])?:'—'?></p></section><section><h3>Client</h3><strong><?=e($c['company'])?></strong><p><?=e($c['contact'])?><?=!empty($c['contact_position'])?' · '.e($c['contact_position']):''?></p><p><?=nl2br(e($c['address']))?></p><p><?=e($c['phone'])?> · <?=e($c['email'])?></p><p>ICE : <?=e($c['ice'])?:'—'?> · IF : <?=e($c['tax_id'])?:'—'?></p></section></div><p class="small muted"><?=e(documentOriginLabel($doc,$s))?></p><?php if(!empty($s['source_quote'])):?><p class="small">Selon devis accepté <?=e($s['source_quote']['number'])?></p><?php endif?><?php if($doc['kind']==='quote'&&!empty($s['valid_until'])):?><p class="small">Valable jusqu’au <?=e($s['valid_until'])?></p><?php endif?><?php if($doc['kind']==='credit'):?><p><strong>À déduire de la facture <?=e($s['source_invoice']['number'])?> du <?=e(localDate($s['source_invoice']['created_at']))?></strong></p><p>Motif : <?=nl2br(e($s['credit_reason']))?></p><?php endif?><h2><?=e($o['title'])?></h2><p><?=nl2br(e($o['description']))?></p><?php require __DIR__.'/document_lines_view.php';?><div class="document-totals"><p><span>HT avant remise</span><strong><?=e(money(decimalString($lineSummary['gross_subtotal'],2)))?></strong></p><p><span>Remises</span><strong><?=e(money(decimalString($lineSummary['discount'],2)))?></strong></p><p><span>HT net</span><strong><?=e(money($doc['subtotal']))?></strong></p><p><span>TVA totale</span><strong><?=e(money($doc['tax']))?></strong></p><p><span><?=$doc['kind']==='credit'?'Total TTC à déduire':'Total TTC'?></span><strong><?=e(money($doc['total']))?></strong></p><?php if($doc['kind']==='invoice'):?><p><span>Avoirs déduits</span><strong><?=e(money(decimalString($summary['credited'],2)))?></strong></p><p><span>Net après avoirs</span><strong><?=e(money(decimalString($summary['total'],2)))?></strong></p><p><span>Solde en faveur du client</span><strong><?=e(money(decimalString($summary['available'],2)))?></strong></p><p><span>Réglé confirmé</span><strong><?=e(money(decimalString($summary['paid'],2)))?></strong></p><p><span>En attente</span><strong><?=e(money(decimalString($summary['pending'],2)))?></strong></p><p><span>Reste dû</span><strong><?=e(money(decimalString($summary['balance'],2)))?></strong></p><?php endif?></div><p>Méthode prévue : <?=e($o['payment_method'])?></p><p>Livraison : <?=e($o['due_date']?:'À convenir')?></p><p class="document-terms"><?=nl2br(e($i['document_terms']))?></p><p class="small muted">Devise : MAD. Les règlements d’une facture affichent la situation actuelle.</p></article>
